package dev.eugheist.tc4modern;
/** WorldGenManaPods scan: ten columns after tree decoration, leave two air blocks under a log. */
public final class ManaPodFeature extends net.minecraft.world.level.levelgen.feature.Feature<net.minecraft.world.level.levelgen.feature.configurations.NoneFeatureConfiguration>{
 public ManaPodFeature(){super(net.minecraft.world.level.levelgen.feature.configurations.NoneFeatureConfiguration.CODEC);}
 @Override public boolean place(net.minecraft.world.level.levelgen.feature.FeaturePlaceContext<net.minecraft.world.level.levelgen.feature.configurations.NoneFeatureConfiguration> c){var level=c.level();var random=c.random();boolean placed=false;for(int i=0;i<10;i++){int x=c.origin().getX()+random.nextInt(16),z=c.origin().getZ()+random.nextInt(16),startX=x,startZ=z;int ground=level.getHeight(net.minecraft.world.level.levelgen.Heightmap.Types.WORLD_SURFACE_WG,x,z);while(ground>level.getMinBuildHeight()&&!level.getBlockState(new net.minecraft.core.BlockPos(x,ground-1,z)).is(net.minecraft.tags.BlockTags.DIRT))ground--;for(int y=ground;y<Math.min(level.getMaxBuildHeight(),ground+64);y++){var at=new net.minecraft.core.BlockPos(x,y,z);if(level.isEmptyBlock(at)&&level.isEmptyBlock(at.below())){var state=BasicsContent.MANA_POD.get().defaultBlockState();if(state.canSurvive(level,at)){state=state.setValue(ManaPodBlock.AGE,3+random.nextInt(5));level.setBlock(at,state,2);if(level.getBlockEntity(at) instanceof ManaPodEntity pod){var primals=thaumcraft.api.aspects.Aspect.getPrimalAspects();pod.aspect=primals.get(random.nextInt(primals.size()));pod.setChanged();}placed=true;break;}}else{x=startX+random.nextInt(4)-random.nextInt(4);z=startZ+random.nextInt(4)-random.nextInt(4);}}}return placed;}
}
